  function downloadFile(name, text, type) {
    var blob = new Blob([text], { type: type });
    var url = URL.createObjectURL(blob);
    var a = document.createElement("a");
    a.href = url; a.download = name;
    document.body.appendChild(a); a.click(); document.body.removeChild(a);
    setTimeout(function () { URL.revokeObjectURL(url); }, 1000);
  }
  function deriveVisual(url) {
    var host;
    try { host = new URL(url).hostname.replace(/^www\./, ""); } catch (e) { host = "link"; }
    var site = host.split(".")[0]; site = site.charAt(0).toUpperCase() + site.slice(1);
    var color = colorFor(host);
    return { icon: { letter: (site.charAt(0) || "?").toUpperCase(), color: color }, preview: { label: site, color: color } };
  }
  function escAttr(s) { return String(s).replace(/&/g, "&amp;").replace(/"/g, "&quot;").replace(/</g, "&lt;").replace(/>/g, "&gt;"); }

  document.getElementById("exportJson").addEventListener("click", function () {
