    downloadFile("bookmarks.html", html, "text/html");
    flash("Bookmarks exported.", "ok");
  });

  function mergeImported(incoming) {
    var existing = load();
    var seen = {}; existing.forEach(function (b) { seen[b.norm || normalize(b.url)] = true; });
    var added = 0, skipped = 0, i = 0;
    incoming.forEach(function (b) {
      if (!b || !b.url || !isValidWebUrl(b.url)) { skipped++; return; }
      var n = normalize(b.url);
      if (seen[n]) { skipped++; return; }
      seen[n] = true; b.norm = n; b.id = "imp" + Date.now() + "_" + (i++);
      existing.push(b); added++;
    });
    persist(existing); renderViewsChips(); render();
    return { added: added, skipped: skipped };
  }
  function importJson(text) {
    var data = JSON.parse(text);
